{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Record C41 reports didanosine human bioavailability of 43 ± 11%, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C67"],
      "claim": "Record C67 reports zidovudine absolute oral bioavailability of 62-68% at 200 mg in adults, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Record C16 reports dapagliflozin absolute oral bioavailability of 78% (90% CI 73-83%) in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple transferred human bioavailability records consistently exceed 20%, including absolute measurements of 43%, 62-68%, and 78%; low-F reports are condition-dependent or uncertain.",
  "evidence_gaps": [
    "Molecule 10 provides only comparative bioavailability language without an absolute F value, so it is uninformative for the threshold.",
    "Some didanosine records under fed or high-dose conditions report F near or below 20%; these are condition-dependent and less applicable to ordinary absolute bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

